$error = '';
$adminPassword = $_ENV['ADMIN_PASSWORD'] ?? '';
function admin_subscriptions_logged_in(): bool { return function_exists('admin_panel_logged_in') ? admin_panel_logged_in() : !empty($_SESSION['admin_articles_logged_in']); }
if (($_GET['action'] ?? '') === 'logout') { unset($_SESSION['admin_articles_logged_in']); redirect_302('admin/subscriptions'); }

if (($_SERVER['REQUEST_METHOD'] ?? 'GET') === 'POST') {
    require_csrf();
    if (admin_password_needs_setup($adminPassword)) { $error = 'ADMIN_PASSWORD belum aman. Ganti nilai ADMIN_PASSWORD di file .env dengan password kuat sebelum login admin.'; }
    elseif (!admin_subscriptions_logged_in()) { if (hash_equals($adminPassword, (string)($_POST['password'] ?? ''))) { $_SESSION['admin_articles_logged_in'] = true; redirect_302('admin/subscriptions'); } $error = 'Password admin salah.'; }
    else {
        $action = (string)($_POST['form_action'] ?? '');
        if ($action === 'save_subscription') {
            $settings = ['enabled'=>!empty($_POST['enabled']),'auto_create_after_paid'=>!empty($_POST['auto_create_after_paid']),'default_cycle'=>(string)($_POST['default_cycle'] ?? 'monthly'),'default_duration_days'=>(int)($_POST['default_duration_days'] ?? 30),'default_grace_days'=>(int)($_POST['default_grace_days'] ?? 3),'reminder_days'=>(string)($_POST['reminder_days'] ?? '7,3,1,0,-1'),'show_on_member_area'=>!empty($_POST['show_on_member_area']),'renewal_message_template'=>(string)($_POST['renewal_message_template'] ?? '')];
            if (subscription_write_settings($settings)) { redirect_302('admin/subscriptions?message=' . rawurlencode('Pengaturan subscription berhasil disimpan.')); }
            $error = 'Pengaturan belum bisa disimpan. Pastikan folder storage writable.';
        }
    }
}

$loggedIn = admin_subscriptions_logged_in();
$settings = $loggedIn ? subscription_read_settings() : subscription_default_settings();
$summary = $loggedIn ? subscription_summary() : [];
$records = $loggedIn ? subscription_read_records() : [];
$cycles = function_exists('subscription_cycle_options') ? subscription_cycle_options() : ['monthly'=>'Bulanan','six_months'=>'6 Bulanan','yearly'=>'Tahunan'];

set_seo(['title'=>'Membership Subscription - Admin','description'=>'Kelola subscription, masa aktif, reminder expiry, dan renewal membership.','robots'=>'noindex, nofollow']);
require_once ROOT_PATH . '/components/layout/head.php';
require_once ROOT_PATH . '/components/layout/header.php';
