uccess"><?=esc($message);?></div><?php endif;?><?php if($error):?><div class="admin-alert admin-alert--error"><?=esc($error);?></div><?php endif;?><?php if(!$loggedIn):?><div class="admin-card admin-login-card"><h2>Login Admin</h2><p>Masukkan password admin untuk membuka Subscription Center.</p><form method="post" class="admin-login-form"><?=csrf_field();?><label>Password Admin</label><input type="password" name="password" required autofocus><button class="admin-btn admin-btn--primary" type="submit">Login</button></form></div><?php else:?><?php admin_panel_render_nav('admin/subscriptions'); ?><div class="admin-grid admin-grid--stats"><div class="admin-card"><span class="admin-badge">Total</span><h2><?= (int)($summary['total'] ?? 0); ?></h2><p>Membership/subscription.</p></div><div class="admin-card"><span class="admin-badge">Aktif</span><h2><?= (int)($summary['active'] ?? 0); ?></h2><p>Masih aktif.</p></div><div class="admin-card"><span class="admin-badge">Grace</span><h2><?= (int)($summary['grace'] ?? 0); ?></h2><p>Masa toleransi.</p></div><div class="admin-card"><span class="admin-badge">Expired</span><h2><?= (int)($summary['expired'] ?? 0); ?></h2><p>Perlu follow-up.</p></div><div class="admin-card"><span class="admin-badge">Reminder</span><h2><?= count((array)($summary['reminders'] ?? [])); ?></h2><p>Jatuh tempo.</p></div></div><div class="sub-grid"><form method="post" class="sub-card"><?=csrf_field();?><input type="hidden" name="form_action" value="save_subscription"><h2>Pengaturan Subscription</h2><label class="sub-check"><input type="checkbox" name="enabled" value="1" <?=!empty($settings['enabled'])?'checked':'';?>> Aktifkan Subscription Center</label><label class="sub-check"><input type="checkbox" name="auto_create_after_paid" value="1" <?=!empty($settings['auto_create_after_paid'])?'checked':'';?>> Otomatis buat subscription setelah payment valid</label><label class="sub-check"><input type="checkbox" name="show_on_member_area" value="1" <?=!empty($settings[